<h2>Generate a responsive typography scale</h2><p class="lead">Create fluid <code>clamp()</code> values that interpolate between minimum and maximum font sizes across a viewport range.</p>
<div class="form-grid"><div class="field"><label for="minV">Minimum viewport (px)</label><input id="minV" type="number" min="1" value="375"></div><div class="field"><label for="maxV">Maximum viewport (px)</label><input id="maxV" type="number" min="1" value="1440"></div><div class="field"><label for="minBase">Body size at min viewport (px)</label><input id="minBase" type="number" min="1" step="any" value="16"></div><div class="field"><label for="maxBase">Body size at max viewport (px)</label><input id="maxBase" type="number" min="1" step="any" value="18"></div><div class="field"><label for="ratio">Modular scale ratio</label><input id="ratio" type="number" min="1.01" step="0.001" value="1.2"></div><div class="field"><label for="steps">Heading steps</label><input id="steps" type="number" min="1" max="8" step="1" value="5"></div></div>
<div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Generate scale</button><button class="btn btn-secondary" id="copy" type="button">Copy CSS</button></div>
<div class="field full"><label for="css">Generated CSS variables</label><textarea id="css" rows="12" readonly></textarea></div><div id="note" class="helper"></div>
<script>
(()=>{const $=id=>document.getElementById(id);let last='';function clamp(min,max,minV,maxV){const slope=(max-min)/(maxV-minV)*100,intercept=min-(slope*minV/100);return `clamp(${min.toFixed(3)}px, calc(${intercept.toFixed(3)}px + ${slope.toFixed(4)}vw), ${max.toFixed(3)}px)`}function build(){const minV=parseFloat($('minV').value),maxV=parseFloat($('maxV').value),minB=parseFloat($('minBase').value),maxB=parseFloat($('maxBase').value),r=parseFloat($('ratio').value),steps=Math.round(parseFloat($('steps').value));if(!(minV>0&&maxV>minV&&minB>0&&maxB>0&&r>1&&steps>=1&&steps<=8)){$('css').value='';$('note').textContent='Use a maximum viewport larger than the minimum and positive font sizes/scale values.';$('note').className='helper danger';return}const lines=[':root {',`  --text-0: ${clamp(minB,maxB,minV,maxV)};`];for(let i=1;i<=steps;i++){lines.push(`  --text-${i}: ${clamp(minB*Math.pow(r,i),maxB*Math.pow(r,i),minV,maxV)};`)}lines.push('}');last=lines.join('\n');$('css').value=last;$('note').textContent='The preferred value is linear between the two viewport anchors and clamped outside that range.';$('note').className='helper'}$('calc').onclick=build;$('copy').onclick=async()=>{if(!last)return;try{await navigator.clipboard.writeText(last);$('note').textContent='CSS copied.'}catch(e){$('css').select();document.execCommand('copy')}};['minV','maxV','minBase','maxBase','ratio','steps'].forEach(id=>$(id).addEventListener('input',build));build()})();
</script>
